import{_ as p,a0 as o,w as d,s as r,ao as l,I as a,a1 as t,A as e,x as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"3 個簡單、優秀的 Linux 網絡監視器 | LCTT x X-CMD","titleTemplate":false,"description":"3 個簡單、優秀的 Linux 網絡監視器 | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"3 個簡單、優秀的 Linux 網絡監視器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"3 個簡單、優秀的 Linux 網絡監視器 | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171019 3 Simple Excellent Linux Network Monitors","title":"3 個簡單、優秀的 Linux 網絡監視器","tag":"201711","desc":""},"relativePath":"201711/20171019 3 Simple Excellent Linux Network Monitors.md","filePath":"[post].md"}'),g={name:"201711/20171019 3 Simple Excellent Linux Network Monitors.md"};function h(u,s,k,c,b,f){const i=o("Link");return d(),r("div",null,[s[31]||(s[31]=l('<h1 id="_3-個簡單、優秀的-linux-網絡監視器" tabindex="-1">3 個簡單、優秀的 Linux 網絡監視器 <a class="header-anchor" href="#_3-個簡單、優秀的-linux-網絡監視器" aria-label="Permalink to “3 個簡單、優秀的 Linux 網絡監視器”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/banner_3.png?itok=iuPcSN4k" alt="network" title="network"></p><p><em>用 iftop、Nethogs 和 vnstat 瞭解更多關於你的網絡連接。</em></p><p>你可以通過這三個 Linux 網絡命令，瞭解有關你網絡連接的大量信息。iftop 通過進程號跟蹤網絡連接，Nethogs 可以快速顯示哪個在佔用你的帶寬，而 vnstat 作為一個很好的輕量級守護進程運行，可以隨時隨地記錄你的使用情況。</p><h3 id="iftop" tabindex="-1">iftop <a class="header-anchor" href="#iftop" aria-label="Permalink to “iftop”">​</a></h3>',5)),a("p",null,[t(i,{href:"http://www.ex-parrot.com/pdw/iftop/"},{default:e(()=>[...s[0]||(s[0]=[n("iftop",-1)])]),_:1}),s[1]||(s[1]=n(" 監聽你指定的網絡接口，並以 ",-1)),s[2]||(s[2]=a("code",null,"top",-1)),s[3]||(s[3]=n(" 的形式展示連接。",-1))]),s[32]||(s[32]=l(`<p>這是一個很好的小工具，用於快速識別佔用、測量速度，並保持網絡流量的總體運行。看到我們使用了多少帶寬是非常令人驚訝的，特別是對於我們這些還記得使用電話線、調製解調器、讓人尖叫的 Kbit 速度和真實的實時波特率的老年人來説。我們很久以前就放棄了波特率，轉而使用比特率。波特率測量信號變化，有時與比特率相同，但大多數情況下不是。</p><p>如果你只有一個網絡接口，可以不帶選項運行 <code>iftop</code>。<code>iftop</code> 需要 root 權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo iftop</span></span></code></pre></div><p>當你有多個接口時，指定要監控的接口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo iftop -i wlan0</span></span></code></pre></div><p>就像 top 一樣，你可以在運行時更改顯示選項。</p><ul><li><code>h</code> 切換幫助屏幕。</li><li><code>n</code> 切換名稱解析。</li><li><code>s</code> 切換源主機顯示，<code>d</code> 切換目標主機。</li><li><code>s</code> 切換端口號。</li><li><code>N</code> 切換端口解析。要全看到端口號，請關閉解析。</li><li><code>t</code> 切換文本界面。默認顯示需要 ncurses。我認為文本顯示更易於閲讀和更好的組織（圖1）。</li><li><code>p</code> 暫停顯示。</li><li><code>q</code> 退出程序。</li></ul><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fig-1_8.png?itok=luKHS5ve" alt="text display" title="text display"></p><p><em>圖 1：文本顯示是可讀的和可組織的。</em></p><p>當你切換顯示選項時，<code>iftop</code> 會繼續測量所有流量。你還可以選擇要監控的單個主機。你需要主機的 IP 地址和網絡掩碼。我很好奇 Pandora 在我那可憐的帶寬中佔用了多少，所以我先用 <code>dig</code> 找到它們的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dig A pandora.com</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>;; ANSWER SECTION:</span></span>
<span class="line"><span>pandora.com.            267     IN      A       208.85.40.20</span></span>
<span class="line"><span>pandora.com.            267     IN      A       208.85.40.50</span></span></code></pre></div>`,11)),a("p",null,[s[5]||(s[5]=n("網絡掩碼是什麼？ ",-1)),t(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/8/how-calculate-network-addresses-ipcalc"},{default:e(()=>[...s[4]||(s[4]=[n("ipcalc",-1)])]),_:1}),s[6]||(s[6]=n(" 告訴我們：",-1))]),s[33]||(s[33]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ipcalc -b 208.85.40.20</span></span>
<span class="line"><span>Address:   208.85.40.20   </span></span>
<span class="line"><span>Netmask:   255.255.255.0 = 24</span></span>
<span class="line"><span>Wildcard:  0.0.0.255  </span></span>
<span class="line"><span>=&gt;</span></span>
<span class="line"><span>Network:   208.85.40.0/24</span></span></code></pre></div><p>現在將地址和網絡掩碼提供給 iftop：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo iftop -F 208.85.40.20/24 -i wlan0</span></span></code></pre></div><p>這不是真的嗎？我很驚訝地發現，我珍貴的帶寬對於 Pandora 很寬裕，每小時使用大約使用 500Kb。而且，像大多數流媒體服務一樣，Pandora 的流量也有峯值，其依賴於緩存來緩解阻塞。</p>`,4)),a("p",null,[s[8]||(s[8]=n("你可以使用 ",-1)),s[9]||(s[9]=a("code",null,"-G",-1)),s[10]||(s[10]=n(" 選項對 IPv6 地址執行相同操作。請參閲手冊頁瞭解 ",-1)),s[11]||(s[11]=a("code",null,"iftop",-1)),s[12]||(s[12]=n(" 的其他功能，包括使用自定義配置文件定製默認選項，並應用自定義過濾器（請參閲 ",-1)),t(i,{href:"http://www.tcpdump.org/manpages/pcap-filter.7.html"},{default:e(()=>[...s[7]||(s[7]=[n("PCAP-FILTER",-1)])]),_:1}),s[13]||(s[13]=n(" 作為過濾器參考）。",-1))]),s[34]||(s[34]=l(`<h3 id="nethogs" tabindex="-1">Nethogs <a class="header-anchor" href="#nethogs" aria-label="Permalink to “Nethogs”">​</a></h3><p>當你想要快速瞭解誰佔用了你的帶寬時，Nethogs 是快速和容易的。以 root 身份運行，並指定要監聽的接口。它顯示了空閒的應用程序和進程號，以便如果你願意的話，你可以殺死它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nethogs wlan0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>NetHogs version 0.8.1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PID USER   PROGRAM              DEV    SENT   RECEIVED       </span></span>
<span class="line"><span>7690 carla /usr/lib/firefox     wlan0 12.494 556.580 KB/sec</span></span>
<span class="line"><span>5648 carla .../chromium-browser wlan0  0.052   0.038 KB/sec</span></span>
<span class="line"><span>TOTAL                                 12.546 556.618 KB/sec</span></span></code></pre></div><p>Nethogs 選項很少：在 kb/s、kb、b 和 mb 之間循環；通過接收或發送的數據包進行排序；並調整刷新之間的延遲。請參閲 <code>man nethogs</code>，或者運行 <code>nethogs -h</code>。</p><h3 id="vnstat" tabindex="-1">vnstat <a class="header-anchor" href="#vnstat" aria-label="Permalink to “vnstat”">​</a></h3>`,5)),a("p",null,[t(i,{href:"http://humdi.net/vnstat/"},{default:e(()=>[...s[14]||(s[14]=[n("vnstat",-1)])]),_:1}),s[15]||(s[15]=n(" 是最容易使用的網絡數據收集器。它是輕量級的，不需要 root 權限。它作為守護進程運行，並記錄你網絡統計信息。",-1)),s[16]||(s[16]=a("code",null,"vnstat",-1)),s[17]||(s[17]=n(" 命令顯示累計的數據：",-1))]),s[35]||(s[35]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -i wlan0</span></span>
<span class="line"><span>Database updated: Tue Oct 17 08:36:38 2017</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   wlan0 since 10/17/2017</span></span>
<span class="line"><span></span></span>
<span class="line"><span>          rx:  45.27 MiB      tx:  3.77 MiB      total:  49.04 MiB</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   monthly</span></span>
<span class="line"><span>                     rx      |     tx      |    total    |   avg. rate</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>       Oct &#39;17     45.27 MiB |    3.77 MiB |   49.04 MiB |    0.28 kbit/s</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>     estimated        85 MiB |       5 MiB |      90 MiB |</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   daily</span></span>
<span class="line"><span>                     rx      |     tx      |    total    |   avg. rate</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>         today     45.27 MiB |    3.77 MiB |   49.04 MiB |   12.96 kbit/s</span></span>
<span class="line"><span>     ------------------------+-------------+-------------+---------------</span></span>
<span class="line"><span>     estimated       125 MiB |       8 MiB |     133 MiB |</span></span></code></pre></div><p>它默認顯示所有的網絡接口。使用 <code>-i</code> 選項選擇單個接口。以這種方式合併多個接口的數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -i wlan0+eth0+eth1</span></span></code></pre></div><p>你可以通過以下幾種方式過濾顯示：</p><ul><li><code>-h</code> 以小時顯示統計數據。</li><li><code>-d</code> 以天數顯示統計數據。</li><li><code>-w</code> 和 <code>-m</code> 按周和月顯示統計數據。</li><li>使用 <code>-l</code> 選項查看實時更新。</li></ul><p>此命令刪除 wlan1 的資料庫，並停止監控它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -i wlan1 --delete</span></span></code></pre></div><p>此命令為網絡接口創建別名。此例使用 Ubuntu 16.04 中的一個奇怪的接口名稱：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstat -u -i enp0s25 --nick eth0</span></span></code></pre></div><p>默認情況下，vnstat 監視 eth0。你可以在 <code>/etc/vnstat.conf</code> 中更改此內容，或在主目錄中創建自己的個人配置文件。請參見 <code>man vnstat</code> 以獲得完整的參考。</p><p>你還可以安裝 <code>vnstati</code> 創建簡單的彩色圖（圖2）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vnstati -s -i wlx7cdd90a0a1c2 -o vnstat.png</span></span></code></pre></div><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fig-2_5.png?itok=HsWJMcW0" alt="vnstati" title="vnstati"></p><p><em>圖 2：你可以使用 vnstati 創建簡單的彩色圖表。</em></p><p>有關完整選項，請參見 <code>man vnstati</code>。</p><hr>`,16)),a("p",null,[s[19]||(s[19]=n("via: ",-1)),t(i,{href:"https://www.linux.com/learn/intro-to-linux/2017/10/3-simple-excellent-linux-network-monitors"},{default:e(()=>[...s[18]||(s[18]=[n("https://www.linux.com/learn/intro-to-linux/2017/10/3-simple-excellent-linux-network-monitors",-1)])]),_:1})]),a("p",null,[s[23]||(s[23]=n("作者：",-1)),t(i,{href:"https://www.linux.com/users/cschroder"},{default:e(()=>[...s[20]||(s[20]=[n("CARLA SCHRODER",-1)])]),_:1}),s[24]||(s[24]=n(" 譯者：",-1)),t(i,{href:"https://github.com/geekpi"},{default:e(()=>[...s[21]||(s[21]=[n("geekpi",-1)])]),_:1}),s[25]||(s[25]=n(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[22]||(s[22]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[28]||(s[28]=n("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[26]||(s[26]=[n("LCTT",-1)])]),_:1}),s[29]||(s[29]=n(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:e(()=>[...s[27]||(s[27]=[n("Linux中國",-1)])]),_:1}),s[30]||(s[30]=n(" 榮譽推出",-1))])])}const v=p(g,[["render",h]]);export{w as __pageData,v as default};
